def take_while_positive(nums):
    result = []
    for value in nums:
        if value <= 0:
            break
        result.append(value)
    return result

def invert_map(mapping):
    result = {}
    for key, value in mapping.items():
        result.setdefault(value, []).append(key)
    for keys in result.values():
        keys.sort()
    return result

