def ordered_unique(items):
    seen = set()
    result = []
    for item in items:
        if item in seen:
            continue
        seen.add(item)
        result.append(item)
    return result

from collections import deque


class Recent:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity 必须为正")
        self.items = deque(maxlen=capacity)

    def add(self, item):
        self.items.append(item)

    def latest(self):
        return list(reversed(self.items))

def flatten(matrix):
    result = []
    for row in matrix:
        if isinstance(row, list):
            result.extend(row)
        else:
            result.append(row)
    return result

def add(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items
